SELECT 'gongkao', '点', 'kp-xc-tutui-qty-point', CAST($${"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"点"}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#fffbeb","borderColor":"#f59e0b","icon":"💡"},"content":[{"type":"paragraph","content":[{"type":"text","text":"核心结论：","marks":[{"type":"bold"}]},{"type":"text","text":"图形中线条交叉明显、出现十字/T字/切点时，优先考虑数点。交点数是最常见的考查方式，需区分普通交点、曲直交点、内外交点。"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"一、题型识别"}]},{"type":"paragraph","content":[{"type":"text","text":"当题干图形出现以下特征时，优先想到「数点」："}]},{"type":"columns","attrs":{"cols":2},"content":[{"type":"column","attrs":{"index":0},"content":[{"type":"paragraph","content":[{"type":"text","text":"图形特征","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"线条较多且交叉密集"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"出现明显的十字交叉、T字形"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"直线与曲线相切或相交"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"图形由多条线段构成，端点清晰"}]}]}]}]},{"type":"column","attrs":{"index":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"考查方向","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"交点总数（所有线交叉的点）"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"曲直交点（曲线与直线的交点）"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"内外交点（框内/框外交点）"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"特殊点（切点、端点、顶点）"}]}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"二、核心规律"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"交点数递增/递减：如 1、2、3、4、(5)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"交点数恒定：每幅图交点数相同"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"交点数奇偶交替：奇、偶、奇、偶"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"曲直交点 = 曲线数 × N：如曲直交点恰好是曲线数的 2 倍"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"内外分开数：框内交点和框外交点分别找规律"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"对称数列：如 1、3、5、3、(1)"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"三、解题步骤"}]},{"type":"textDiagram","attrs":{"language":"mermaid"},"content":[{"type":"text","text":"flowchart TD\n    A[观察图形特征] --> B{线条交叉明显?}\n    B -->|是| C[数交点总数]\n    B -->|否| D{直线曲线混合?}\n    D -->|是| E[数曲直交点]\n    D -->|否| F{有外框?}\n    F -->|是| G[内外分开数]\n    F -->|否| H[考虑其他规律]\n    C --> I{找规律}\n    E --> I\n    G --> I\n    I --> J[代入选项验证]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"四、真题精讲"}]},{"type":"paragraph","content":[{"type":"text","text":"【例题】给出五个图形，每个图形由若干直线和曲线组成。图形 1 有 4 个交点，图形 2 有 6 个，图形 3 有 2 个，图形 4 有 4 个，图形 5 有 8 个。问号处应选？","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"推导过程："}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"观察：每个图形都有直线和曲线混合，线条交叉明显 → 考虑数点"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"数交点总数：4、6、2、4、8，无明显等差规律"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"转换思路：数曲直交点（曲线与直线的交点）。发现每幅图的曲直交点数恰好是曲线数的 2 倍"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"图形 5 有 4 条曲线，曲直交点 = 8，验证成立"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"问号处应选曲直交点 = 曲线数 × 2 的选项"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"五、易错点"}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#fef2f2","borderColor":"#ef4444","icon":"⚠️"},"content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"不要只数「所有交点」，曲直交点、内外交点可能是隐藏考点"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"端点和切点容易漏数，尤其是曲线与直线相切时"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"有外框的图形一定要考虑「框内/框外交点」分开数"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"T字形交叉点也是交点，不要忽略"}]}]}]}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#eff6ff","borderColor":"#3b82f6","icon":"📊"},"content":[{"type":"paragraph","content":[{"type":"text","text":"刷题建议：","marks":[{"type":"bold"}]},{"type":"text","text":"数点类题目在图形推理中占比约 8%，属于中频考点。建议优先掌握「曲直交点」和「内外分开数」两个进阶技巧，它们是近年考试的热门方向。每天练习 5-10 道数点题，重点训练「看到图形特征 → 立刻反应考查方向」的条件反射。"}]}]}]}$$ AS jsonb), NULL, '图形推理数量类-点的核心考点：交点数、曲直交点、内外交点的识别与解题方法。', category_node.id, CAST('["图形推理", "数量规律", "点", "交点", "曲直交点"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xc_tuTui_qty_point", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
